fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We know v is non-empty and sorted in non-decreasing order,
    // and that k appears at least once in v.

    // We'll maintain a search window [left, right], both inclusive.
    let mut left = 0;
    let mut right = v.len() - 1;

    // Loop until the window collapses to a single index.
    while left < right {
        // Prevent overflow and bias towards the lower half on ties.
        let mid = left + (right - left) / 2;

        // If the middle element is strictly less than k, 
        // then k must be to the right of mid.
        if v[mid] < k {
            left = mid + 1;
        } else {
            // Otherwise k is at mid or to the left of mid.
            right = mid;
        }
    }

    // At this point left == right and must point to an occurrence of k.
    left
}

